const baselineFailures = safeguards(files).filter(([, fn]) => !fn()).map(([guard]) => guard);
if (baselineFailures.length) {
  console.error(`Baseline safeguard failure(s); mutation scoring is invalid until these are fixed: ${baselineFailures.join(", ")}`);
  process.exit(1);
}

let fail = 0;
for (const [name, file, replacement, to] of mutations) {
  const original = files[file];
  const changed = original.replace(replacement, to);
  const mutationApplied = changed !== original;
  const mutated = { ...files, [file]: changed };
  const failedGuards = safeguards(mutated).filter(([, fn]) => !fn()).map(([guard]) => guard);
  const ok = mutationApplied && failedGuards.length > 0;
  console.log(`${ok ? "PASS" : "FAIL"} mutation detected: ${name}${ok ? ` -> ${failedGuards.join(", ")}` : mutationApplied ? " (no guard failed)" : " (mutation did not apply)"}`);
  if (!ok) fail++;
}
if (fail) process.exit(1);
console.log(`Mutation suite PASS (${mutations.length}/${mutations.length} deliberate safeguard removals detected).`);
